Here's a simple, robust, and well-commented TCP/IP server in C using POSIX sockets. It handles multiple clients sequentially (single-threaded, blocking I/O) — suitable for learning and lightweight use. For production, consider threading, `select()`/`epoll`, or `fork()`.

### ✅ Features:
- IPv4 & IPv6 support (via `getaddrinfo`)
- Proper error checking and cleanup
- Handles client disconnection gracefully
- Echoes received data back to client
- Uses `SO_REUSEADDR` to allow rapid restart
- Clean resource cleanup (sockets, memory)

---

### 📝 `tcp_server.c`

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

#define PORT "8080"           // Port to listen on
#define BACKLOG 10            // Max pending connections
#define BUFFER_SIZE 1024

int main(void) {
    int sockfd, new_fd;
    struct addrinfo hints, *servinfo, *p;
    struct sockaddr_storage client_addr;
    socklen_t client_addr_len;
    char client_ip[INET6_ADDRSTRLEN];
    int yes = 1;
    char buffer[BUFFER_SIZE];
    int numbytes;

    // Setup hints for getaddrinfo
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;     // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP
    hints.ai_flags = AI_PASSIVE;     // Use my IP

    // Get address info
    int rv;
    if ((rv = getaddrinfo(NULL, PORT, &hints, &servinfo)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(rv));
        return 1;
    }

    // Loop through results and bind to first valid one
    for (p = servinfo; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd == -1) {
            continue;
        }

        // Allow reuse of port (so we can restart quickly)
        if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(int)) == -1) {
            perror("setsockopt");
            close(sockfd);
            continue;
        }

        if (bind(sockfd, p->ai_addr, p->ai_addrlen) == 0) {
            break; // Success
        }

        close(sockfd);
    }

    if (p == NULL) {
        fprintf(stderr, "Failed to bind to any address.\n");
        freeaddrinfo(servinfo);
        return 2;
    }

    freeaddrinfo(servinfo); // All done with this

    // Listen
    if (listen(sockfd, BACKLOG) == -1) {
        perror("listen");
        close(sockfd);
        return 3;
    }

    printf("Server listening on port %s...\n", PORT);

    // Main server loop
    while (1) {
        client_addr_len = sizeof client_addr;
        new_fd = accept(sockfd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (new_fd == -1) {
            perror("accept");
            continue;
        }

        // Get client IP and port
        inet_ntop(client_addr.ss_family,
                  (client_addr.ss_family == AF_INET) ?
                      (const void*)&(((struct sockaddr_in*)&client_addr)->sin_addr) :
                      (const void*)&(((struct sockaddr_in6*)&client_addr)->sin6_addr),
                  client_ip, sizeof client_ip);
        printf("Accepted connection from %s\n", client_ip);

        // Handle client (echo server)
        while (1) {
            memset(buffer, 0, sizeof buffer);
            numbytes = recv(new_fd, buffer, BUFFER_SIZE - 1, 0);
            if (numbytes == 0) {
                printf("Client %s disconnected.\n", client_ip);
                break;
            } else if (numbytes == -1) {
                perror("recv");
                break;
            }

            // Echo back the message
            if (send(new_fd, buffer, numbytes, 0) == -1) {
                perror("send");
                break;
            }
        }

        close(new_fd); // Close client socket
    }

    // Cleanup (unreachable in infinite loop, but good practice)
    close(sockfd);
    return 0;
}
```

---

### 🛠️ How to Compile & Run

```bash
gcc -o tcp_server tcp_server.c
./tcp_server
```

Then test with `telnet` or `nc`:

```bash
# In another terminal
telnet 127.0.0.1 8080
# or
nc 127.0.0.1 8080
```

Type messages → server echoes them back.

> 💡 **Note**: Press `Ctrl + ]` then type `quit` in `telnet`, or `Ctrl + D` in `nc` to close.

---

### ⚙️ Want Concurrency?
For handling multiple clients *simultaneously*, replace the `while(1)` client loop with `fork()` or use `pthread_create()`. Example `fork()` addition:

```c
// Inside the accept loop, right after new_fd is created:
if (fork() == 0) {  // Child process
    close(sockfd);  // Child doesn't need listener
    // ... handle client (echo loop) ...
    close(new_fd);
    exit(0);
} else {
    close(new_fd);  // Parent closes client socket
}
```

Let me know if you'd like the **multithreaded**, **`select()`-based**, or **IPv6-only** version.

Happy coding! 🖥️

